param([int]$Year=2007,[int]$Month=1,[string]$RunId='',[string]$ProjectRoot='F:\AER_SHARED_PIPELINE')
$ErrorActionPreference='Stop'
if([string]::IsNullOrWhiteSpace($RunId)){$RunId=('produce\run_{0:D4}{1:D2}_month_001' -f $Year,$Month)}elseif($RunId -notmatch '^produce[\\/]run_[A-Za-z0-9_-]+$'){if($RunId -match '^[A-Za-z0-9_-]+$'){$RunId="produce\$RunId"}else{throw 'RunId must be produce\run_<id> (or a bare run_<id>, which is placed under produce).'}}
$RunId=$RunId -replace '/','\'
$runRoot=Join-Path $ProjectRoot "runs\$RunId";$logRoot=Join-Path $runRoot 'logs\full_pipeline';New-Item -ItemType Directory -Force -Path $runRoot,$logRoot|Out-Null
$initialCsv=Join-Path $runRoot 'date_inventory_initial.csv';$finalCsv=Join-Path $runRoot 'finalized_dates.csv';$matlab='E:\tool\matlab2025a\bin\matlab.exe'
function Test-NasPathRetry([string]$p,[string]$label){for($n=1;$n -le 5;$n++){if(Test-Path -LiteralPath $p){if($n -gt 1){Write-Output "NAS_PATH_PASS $label $n/5 $p"};return $true};if($n-lt 5){Write-Warning "NAS_PATH_RETRY $label $n/5 $p";Start-Sleep -Seconds (2*$n)}};Write-Warning "NAS_PATH_MISSING $label 5/5 $p";return $false}
function SuccessPath([string]$kind,[datetime]$d){$yy=$d.ToString('yyyy');$mm=$d.ToString('MM');$dd=$d.ToString('dd');switch($kind){'tall'{Join-Path $ProjectRoot "products\tall\t_all\tall__ap-final-v1__era5-real__adapter-v1__qc-v1\$yy\$mm\$dd\_SUCCESS"};'stats'{Join-Path $ProjectRoot "products\chapter5\calipso_stats\stats__ap-final-v1__era5-real__adapter-v1__qc-v1__stats-v1\$yy\$mm\$dd\_SUCCESS"};'clear'{Join-Path $ProjectRoot "products\chapter5\clear_air_stats\clear__ap-final-v1__grid5deg__z60m__clear-v1\$yy\$mm\$dd\_SUCCESS"};'ccn'{Join-Path $ProjectRoot "products\ccn\ccn_grid\ccn__ap-final-v1__era5-real__grid5deg__ccn-v1\$yy\$mm\$dd\_SUCCESS"}}}
function Test-Daily([datetime]$d,[string[]]$k){return @($k|Where-Object{-not(Test-Path -LiteralPath (SuccessPath $_ $d))}).Count -eq 0}
function Invoke-Matlab([string]$label,[string]$command,[hashtable]$envs){$log=Join-Path $logRoot "$label`_matlab.log";$err=Join-Path $logRoot "$label`_launcher.err";foreach($k in $envs.Keys){Set-Item "Env:$k" $envs[$k]};try{$p=Start-Process $matlab -ArgumentList @('-logfile',$log,'-batch',$command) -RedirectStandardError $err -Wait -PassThru -WindowStyle Hidden}finally{foreach($k in $envs.Keys){Remove-Item "Env:$k" -ErrorAction SilentlyContinue}};if($p.ExitCode-ne 0){throw "MATLAB failed: $label; see $log"}}
# PHASE 1: sole raw-source discovery for this run.
$start=Get-Date -Year $Year -Month $Month -Day 1;$end=$start.AddMonths(1);$initial=[System.Collections.Generic.List[object]]::new()
for($d=$start;$d-lt $end;$d=$d.AddDays(1)){$raw="Z:\CALIPSO_MAT_FINAL\CHAPTER5_AP\05kmAP\$Year\$($d.ToString('yyyy_MM_dd')).mat";$era="Z:\ERA5\mat\$($d.ToString('yyyy'))\$($d.ToString('MM'))\$($d.ToString('dd'))";if(-not(Test-NasPathRetry $raw 'final_mat')){$initial.Add([pscustomobject]@{Date=$d.ToString('yyyy-MM-dd');Status='skipped';Reason='missing_final_mat'});continue};if(-not(Test-NasPathRetry $era 'era5_day_dir')){$initial.Add([pscustomobject]@{Date=$d.ToString('yyyy-MM-dd');Status='skipped';Reason='missing_era5_mat'});continue};$initial.Add([pscustomobject]@{Date=$d.ToString('yyyy-MM-dd');Status='eligible';Reason=''})}
$initial|Export-Csv -LiteralPath $initialCsv -NoTypeInformation -Encoding UTF8
# PHASE 2: frozen initial list; reuse successes and build gaps only.
foreach($row in $initial|Where-Object Status -eq 'eligible'){$d=[datetime]$row.Date;if(-not(Test-Daily $d @('tall','stats','clear'))){Invoke-Matlab "daily_$($d.ToString('yyyyMMdd'))" "run('$ProjectRoot\code\batch\run_chapter5_day_batch.m')" @{CHAPTER5_BATCH_DATE=$row.Date}};if(-not(Test-Daily $d @('ccn'))){Invoke-Matlab "ccn_$($d.ToString('yyyyMMdd'))" "run('$ProjectRoot\code\batch\run_ccn_day_batch.m')" @{CCN_BATCH_DATE=$row.Date;CCN_RUN_ROOT=$runRoot}}}
# Freeze final coverage.  All downstream stages use exactly this CSV.
$final=[System.Collections.Generic.List[object]]::new();foreach($row in $initial){$d=[datetime]$row.Date;if($row.Status-eq 'skipped'){$final.Add($row);continue};if(-not(Test-Daily $d @('tall','stats','clear','ccn'))){throw "Daily gate failed: $($row.Date)"};$final.Add([pscustomobject]@{Date=$row.Date;Status='ready';Reason=''})};$final|Export-Csv -LiteralPath $finalCsv -NoTypeInformation -Encoding UTF8
# PHASE 3: aggregators never rescan raw roots.
$env:FULL_MONTH_RUN_ID=$RunId;$env:FULL_MONTH_YEAR=$Year;$env:FULL_MONTH_MONTH=$Month;$env:FULL_MONTH_FINALIZED_DATES=$finalCsv
try{Invoke-Matlab 'monthly_aggregators' "run('$ProjectRoot\code\batch\run_monthly_aggregators.m')" @{};Invoke-Matlab 'monthly_plots' "run('$ProjectRoot\code\batch\run_existing_month_plots.m')" @{}}finally{Remove-Item Env:FULL_MONTH_RUN_ID,Env:FULL_MONTH_YEAR,Env:FULL_MONTH_MONTH,Env:FULL_MONTH_FINALIZED_DATES -ErrorAction SilentlyContinue}
Write-Output "FULL_MONTH_PRODUCTS_READY $Year-$('{0:D2}' -f $Month) RUN=$RunId FINALIZED_DATES=$finalCsv"
